DROP TABLE IF EXISTS `atk_comments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `atk_comments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  `content` longtext COLLATE utf8mb4_general_ci,
  `page_key` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `site_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `user_id` bigint unsigned DEFAULT NULL,
  `ua` longtext COLLATE utf8mb4_general_ci,
  `ip` longtext COLLATE utf8mb4_general_ci,
  `rid` bigint unsigned DEFAULT NULL,
  `is_collapsed` tinyint(1) DEFAULT '0',
  `is_pending` tinyint(1) DEFAULT '0',
  `is_pinned` tinyint(1) DEFAULT '0',
  `vote_up` bigint DEFAULT NULL,
  `vote_down` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_atk_comments_deleted_at` (`deleted_at`),
  KEY `idx_atk_comments_page_key` (`page_key`),
  KEY `idx_atk_comments_site_name` (`site_name`),
  KEY `idx_atk_comments_user_id` (`user_id`),
  KEY `idx_atk_comments_rid` (`rid`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

